"""Rebuild human-readable slot QA handoff from received evidence; no network."""
import json
from run_demo_qa import ROOT,now,save
from scope_slots import build
FOCUS=['CatsLoveYummy','RedHotChilliChickens','MysticReels','ChickenFire','YommiRush','JokerVsJoker','GrandPatron7rst','KeepersOfTheSecret7rst','WildMoonThieves','LuckyLadyClover','AllLuckyClover','DigDigDigger','LuckyDragonMultiDiceX']
def main():
 scope=build();audit=json.loads((ROOT/'live-audit.json').read_text(encoding='utf8'));validation=json.loads((ROOT/'validation.json').read_text(encoding='utf8'));ids={e['game_id'] for e in scope['games'] if e['in_current_scope'] and e['game_id']};selected=[r for r in audit['reports'] if r['game_id'] in ids]
 summary=dict(updated_at=now(),scope='Slots only; fresh official FUN demos, native money and responses',slot_products=scope['slot_products'],slot_public_demos=scope['slot_public_demos'],slot_no_public_demo_link=scope['slot_no_public_demo_link'],excluded_non_slot_products=scope['excluded_products'],execution_plans_fulfilled=scope['slots_with_execution_plan_fulfilled'],runtime_pending_slots=scope['runtime_pending_slots'],unavailable_launches=scope['public_launch_unavailable_slots'],financial_review_slots=scope['financial_review_slots'],historical_financial_findings_preserved=scope['historical_financial_findings_preserved'],historical_failed_checks_preserved=scope['historical_failed_checks_preserved'],status_counts=scope['slot_status_counts'],checks_passed=sum(r.get('passed',0) for r in selected),checks_failed=sum(r.get('failed',0) for r in selected),audit_errors=[r['game_id'] for r in selected if r.get('audit_error')],offline_tests=validation['live_tests']['passed'],all_runtime_work_finished=not scope['runtime_pending_slots'])
 save(ROOT/'slot-results.json',summary)
 lines=['# BGaming: resultado de los slots','',f"Actualizado: {summary['updated_at']}",'',f"Alcance: **{summary['slot_products']} slots** del catálogo; **{summary['slot_public_demos']}** tienen enlace de demo y **{summary['slot_no_public_demo_link']}** no. Los **{summary['excluded_non_slot_products']}** productos de otras categorías quedan fuera de nuevas pruebas. Se conservan sus registros históricos.",'',f"Planes recorridos: **{summary['execution_plans_fulfilled']} de {summary['slot_public_demos']} demos de slots**. Pendientes de ejecución: {', '.join(summary['runtime_pending_slots']) or 'ninguno'}. Enlaces de lanzamiento no disponibles en la comprobación: {', '.join(summary['unavailable_launches']) or 'ninguno'}.",'',f"Auditoría actual de slots: {summary['checks_passed']} comprobaciones correctas y {summary['checks_failed']} fallidas; {len(summary['audit_errors'])} errores al leer auditorías. Pruebas offline: {summary['offline_tests']} correctas. Un cierre de ronda y una conciliación monetaria son resultados separados.",'','## Casos cerrados y recuperados','','| Slot | Modos declarados | Resultado actual |','|---|---:|---|']
 for gid in FOCUS:
  r=json.loads((ROOT/'live'/(gid+'.json')).read_text(encoding='utf8'));status=r['status']
  if gid in summary['financial_review_slots'] and gid not in summary['runtime_pending_slots']:status='Recorrido; incidencia histórica de saldo conservada'
  lines.append(f"| [{gid}](live/{gid}.json) | {len(r.get('declared_modes',[]))} | {status} |")
 lines+=['','## Historial de incidencias de saldo','','Las sesiones nuevas de los cuatro juegos cerraron todos sus modos y conciliaron sin diferencias. Los importes y fallos anteriores siguen en archivos históricos inmutables, enlazados con su SHA-256 desde cada informe actual. Las 30 comprobaciones históricas fallidas conservan ese resultado y se cuentan separadas de la auditoría actual; la revalidación no demuestra cuál fue la causa de los saltos anteriores:','', '| Slot | Diferencia observada |','|---|---|','| TheGodfather3PillarsOfPower | Wallet nativo 89900 → 100000 durante una continuación, sin premio que explique +10100. |','| RocketEruptionTripleBlast | Wallet nativo 98012 → 100000; +1988 no explicado por el premio de esa respuesta. |','| LuckyDragonMultiDiceX | El primer activador cerrado dejó una diferencia de −20 frente al contexto anterior; el segundo concilió desde una inicialización nueva. |','| DigDigDigger | La pérdida de la primera elección cerró con wallet 99990 → 100000; las compras y las seis elecciones posteriores conciliaron desde sus puntos iniciales registrados. |','','[Revisión de fuente y aritmética de Godfather/Rocket](finance_observations_review_20261029_bonus_choices.json). La hipótesis de renovación FUN no está demostrada por esas respuestas. Los informes nuevos contienen la validación independiente de las sesiones actuales; las incidencias antiguas permanecen archivadas.','','## Disponibilidad y límites','','[Princess of Sky](https://bgaming.com/games/princess-of-sky) sigue publicando el mismo enlace de demo. La apertura directa registrada devolvió HTTP404 antes de jugar: [captura de disponibilidad](live/PrincessOfSky.json), [referencia de la ficha actual](protocols/PrincessOfSky.current-product-demo.json). Los 24 slots sin enlace público se conservan en el catálogo sin inventar identificadores ni sesiones.','','Las elecciones internas conservan su contexto: Wild Moon Thieves tiene 16 puertas iniciales comprobadas; Lucky Lady Clover tiene seis elecciones semánticas comprobadas; All Lucky Clover conserva sus cuatro variantes; Dig conserva nueve compras, un activador y seis elecciones de riesgo. No se enumeran infinitas secuencias de riesgo, todas las permutaciones de símbolos ni resultados de jackpot que no aparecieron.','','Las dos solicitudes históricas inciertas de ChickenHalloween y SpiderCircusHoldAndWin siguen archivadas con resultado original desconocido. Las pruebas posteriores usaron contextos independientes; no se repitieron esos POST. Ver [auditoría de interrupción](interruption-audit.json).','','## Entregables y reproducción','','- [Integración y referencias HAR originales](INTEGRATION.md).','- [Catálogo completo normalizado](catalog-live.json) y [alcance por slot](slot-scope.json).','- [Resumen estructurado](slot-results.json), [estado de integración](qa-status.json) y [auditoría de importes/estados](live-audit.json).','- [Verificación de privacidad](privacy-live.json); credenciales y originales de transporte permanecen fuera del servidor HTTP.','','La reconstrucción de los informes no abre juegos: `python -X utf8 audit_live.py`, `python -X utf8 scope_slots.py`, `python -X utf8 snapshot_qa.py` y `python -X utf8 write_slot_results.py`. Las pruebas offline se reproducen con `python -X utf8 -m unittest discover -s . -p "test_*.py" -q`.']
 (ROOT/'SLOT-RESULTS.md').write_text('\n'.join(lines)+'\n',encoding='utf8');print(json.dumps(summary,ensure_ascii=False))
if __name__=='__main__':main()
